@Finset.prod_univ_sum : ∀ {ι : Type u_1} {R : Type u_2} [inst : CommSemiring R] [inst_1 : DecidableEq ι]
  {κ : ι → Type u_3} [inst_2 : Fintype ι] (t : (i : ι) → Finset (κ i)) (f : (i : ι) → κ i → R),
  ∏ i, ∑ j ∈ t i, f i j = ∑ x ∈ Fintype.piFinset t, ∏ i, f i (x i)
@Fintype.prod_sum : ∀ {ι : Type u_1} {R : Type u_2} [inst : Fintype ι] [inst_1 : CommSemiring R]
  [inst_2 : DecidableEq ι] {κ : ι → Type u_3} [inst_3 : (i : ι) → Fintype (κ i)] (f : (i : ι) → κ i → R),
  ∏ i, ∑ j, f i j = ∑ x, ∏ i, f i (x i)
@Finset.prod_fiberwise : ∀ {ι : Type u_1} {κ : Type u_2} {M : Type u_3} [inst : CommMonoid M] [inst_1 : DecidableEq κ]
  [inst_2 : Fintype κ] (s : Finset ι) (g : ι → κ) (f : ι → M), ∏ j, ∏ i ∈ s with g i = j, f i = ∏ i ∈ s, f i
@Finset.prod_const : ∀ {ι : Type u_1} {M : Type u_2} {s : Finset ι} [inst : CommMonoid M] (b : M),
  ∏ _x ∈ s, b = b ^ s.card
Fintype.equivFin : (α : Type u_1) → [inst : Fintype α] → α ≃ Fin (Fintype.card α)
@Equiv.sum_comp : ∀ {ι : Type u_1} {κ : Type u_2} {M : Type u_3} [inst : Fintype ι] [inst_1 : Fintype κ]
  [inst_2 : AddCommMonoid M] (e : ι ≃ κ) (g : κ → M), ∑ i, g (e i) = ∑ i, g i
@Fintype.sum_bool : ∀ {α : Type u_1} [inst : AddCommMonoid α] (f : Bool → α), ∑ b, f b = f true + f false
@Finite.injective_iff_surjective : ∀ {α : Type u_1} [Finite α] {f : α → α}, Function.Injective f ↔ Function.Surjective f
@Fintype.card_fun : ∀ {α : Type u_1} {β : Type u_2} [inst : DecidableEq α] [inst_1 : Fintype α] [inst_2 : Fintype β],
  Fintype.card (α → β) = Fintype.card β ^ Fintype.card α
@Finset.card_eq_one : ∀ {α : Type u_1} {s : Finset α}, s.card = 1 ↔ ∃ a, s = {a}
@Fintype.piFinset_univ : ∀ {α : Type u_1} {β : α → Type u_2} [inst : DecidableEq α] [inst_1 : Fintype α]
  [inst_2 : (a : α) → Fintype (β a)], (Fintype.piFinset fun a => Finset.univ) = Finset.univ

